package com.yeyamo_mobile.api.referral_service.infrastructure.cache;
import java.time.*;import java.util.OptionalLong;import org.slf4j.*;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.stereotype.Component;import com.yeyamo_mobile.api.referral_service.application.port.FraudCounterPort;
@Component public class RedisFraudCounterAdapter implements FraudCounterPort{private static final Logger log=LoggerFactory.getLogger(RedisFraudCounterAdapter.class);private final StringRedisTemplate redis;public RedisFraudCounterAdapter(StringRedisTemplate r){redis=r;}public OptionalLong incrementDaily(String user){try{String key="referral:daily:"+LocalDate.now(ZoneOffset.UTC)+":"+user;Long value=redis.opsForValue().increment(key);if(value!=null&&value==1)redis.expire(key,Duration.ofDays(2));return value==null?OptionalLong.empty():OptionalLong.of(value);}catch(RuntimeException e){log.warn("Redis anti-fraud counter unavailable: {}",e.getMessage());return OptionalLong.empty();}}public void evictCode(String code){try{redis.delete("referral:code:"+code.toUpperCase(java.util.Locale.ROOT));}catch(RuntimeException e){log.debug("Referral cache unavailable: {}",e.getMessage());}}}
